import{_ as a,o as t,c as i,a3 as r}from"./chunks/framework.DhF4LrUq.js";const p=JSON.parse('{"title":"Security model","description":"","frontmatter":{},"headers":[],"relativePath":"concepts/security-model.md","filePath":"concepts/security-model.md"}'),n={name:"concepts/security-model.md"};function o(s,e,l,d,c,h){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="security-model" tabindex="-1">Security model <a class="header-anchor" href="#security-model" aria-label="Permalink to &quot;Security model&quot;">​</a></h1><p>ShipperDog&#39;s security posture is fail-closed by construction: deny by default, conceal what callers may not know, record everything, and never mutate what has been promised. This page is the user-facing summary of the guarantees your security and compliance reviewers will ask about.</p><h2 id="immutable-artifacts-permanent-history" tabindex="-1">Immutable artifacts, permanent history <a class="header-anchor" href="#immutable-artifacts-permanent-history" aria-label="Permalink to &quot;Immutable artifacts, permanent history&quot;">​</a></h2><ul><li><strong>Artifacts are write-once.</strong> A binary is stored once under a content-addressed key; re-uploading identical content registers a new artifact, and there is no overwrite or delete anywhere. The SHA-256 is proven at upload, re-proved at validation, and pinned in every release manifest.</li><li><strong>Version sets freeze with distribution.</strong> The moment a version carries any release — a draft counts — its artifact set is frozen. Corrections are new versions, never edits in place.</li><li><strong>History is never rewritten.</strong> Audit events, release timelines, promotion timelines, gate results, approval rounds, and revocation records are append-only. Rollback and revocation stop distribution; they delete nothing.</li></ul><h2 id="the-signed-url-download-path" tabindex="-1">The signed-URL download path <a class="header-anchor" href="#the-signed-url-download-path" aria-label="Permalink to &quot;The signed-URL download path&quot;">​</a></h2><p>Testers never receive storage locations, keys, or proxy tokens. Downloading runs the full seven-layer authorization decision (<a href="/shipperdog/snapshot/concepts/authorization">authorization</a>), and only an ALLOW mints a short-lived signed URL — bounded at or under 15 minutes, and structurally never outliving the revocation backstop: the platform refuses to start if the URL lifetime would exceed the decision-cache window that bounds revocation latency. A revoked grant, a suspended tester, or a rolled-back release denies the very next decision; any URL already minted dies within its bounded minutes.</p><h2 id="concealment" tabindex="-1">Concealment <a class="header-anchor" href="#concealment" aria-label="Permalink to &quot;Concealment&quot;">​</a></h2><p>Authorization failures are indistinguishable from absence: a denied caller receives the byte-identical <code>404</code> a genuine miss produces, with no hint of which check failed. Existence is treated as information. The details of who was denied what live in the audit trail, available to administrators — never in HTTP responses to strangers.</p><h2 id="tenant-isolation" tabindex="-1">Tenant isolation <a class="header-anchor" href="#tenant-isolation" aria-label="Permalink to &quot;Tenant isolation&quot;">​</a></h2><p>Isolation is enforced at two layers (endpoint and database query construction — see <a href="/shipperdog/snapshot/concepts/tenancy-isolation">tenancy and isolation</a>), guarded by architecture tests, and proven continuously by an automated cross-tenant test suite that runs on every build. Cross-tenant access by platform administrators is the sanctioned, explicitly audited exception — never available to organization roles.</p><h2 id="credentials-and-secrets" tabindex="-1">Credentials and secrets <a class="header-anchor" href="#credentials-and-secrets" aria-label="Permalink to &quot;Credentials and secrets&quot;">​</a></h2><ul><li>Passwords are Argon2id-hashed with parseable parameters (raisable without invalidating accounts); lockout and reset flows are timing-uniform.</li><li>Provider client secrets, store credentials (Apple, Google Play), and webhook HMAC secrets live behind secret-store references the platform holds — secret material is written once at configuration time and never echoed again. Store credentials follow a delegation chain (organization default, application override, environment override — production credentials stay distinct from QA).</li><li>Personal access tokens, SCIM connector tokens, and telemetry tokens are shown exactly once and stored only as SHA-256 digests.</li><li>Session tokens rotate on every refresh; reuse of a rotated token revokes the whole family. Role demotions, membership removals, and tester deactivation revoke sessions in the same act.</li></ul><h2 id="the-audit-trail-and-siem" tabindex="-1">The audit trail and SIEM <a class="header-anchor" href="#the-audit-trail-and-siem" aria-label="Permalink to &quot;The audit trail and SIEM&quot;">​</a></h2><p>Every security-relevant operation writes an append-only audit event — who, what, when, from where, against which tenant/application/version/ artifact, with before/after and reason where applicable: logins and denials, role changes, artifact uploads, approval signatures, gate overrides, promotions, downloads, grant revocations, SSO events. Audit streams export to your SIEM over HTTPS collectors or batched bucket deliveries, with a delivery ledger, dead-letter handling, and replay.</p><h2 id="fail-closed-governance" tabindex="-1">Fail-closed governance <a class="header-anchor" href="#fail-closed-governance" aria-label="Permalink to &quot;Fail-closed governance&quot;">​</a></h2><ul><li><strong>Gates and policies block on missing data</strong> — <code>NO_DATA</code> is not a pass.</li><li><strong>Unresolvable approval policies fail closed</strong> — a dangling policy name refuses the crossing rather than silently running a weaker chain.</li><li><strong>Overrides and acknowledges are exceptional, audited, and reason-mandatory</strong> — one governed exception per fact, never a routine bypass.</li><li><strong>ABAC policies can only narrow access</strong> — there is no allow outcome.</li></ul><h2 id="hardening-details" tabindex="-1">Hardening details <a class="header-anchor" href="#hardening-details" aria-label="Permalink to &quot;Hardening details&quot;">​</a></h2><p>Rate limiting guards the login and download tiers. Security headers (strict CSP, HSTS, frame denial) ship on the console, portal, and API origins. Webhook receivers verify HMAC signatures constant-time over a rotating credential list with a replay window. SAML assertions verify against pinned certificates with wrapping and replay defenses. The platform&#39;s own e2e surfaces run against the same posture CI grades.</p><h2 id="where-to-go-deeper" tabindex="-1">Where to go deeper <a class="header-anchor" href="#where-to-go-deeper" aria-label="Permalink to &quot;Where to go deeper&quot;">​</a></h2><ul><li><a href="/shipperdog/snapshot/concepts/authorization">Authorization</a> — the decision chain</li><li><a href="/shipperdog/snapshot/concepts/identity-sso">Identity and SSO</a> — the credential postures</li><li>Developer detail: the <a href="https://github.com/ShristiLabs/shipperdog/blob/main/docs/authentication.md" target="_blank" rel="noreferrer">authentication</a>, <a href="https://github.com/ShristiLabs/shipperdog/blob/main/docs/audit.md" target="_blank" rel="noreferrer">audit</a>, <a href="https://github.com/ShristiLabs/shipperdog/blob/main/docs/siem.md" target="_blank" rel="noreferrer">SIEM</a>, and <a href="https://github.com/ShristiLabs/shipperdog/blob/main/docs/webhooks.md" target="_blank" rel="noreferrer">webhooks</a> docs, plus the ADRs (token storage, object storage, tenant isolation) in the repository&#39;s docs directory.</li></ul>',20)])])}const m=a(n,[["render",o]]);export{p as __pageData,m as default};
